import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p72_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor stark_conv_transpose3d_fast(torch::Tensor input, torch::Tensor weight);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose3d_fast", &stark_conv_transpose3d_fast,
          "Specialized grouped ConvTranspose3d forward (float32 CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized ConvTranspose3d kernel for:
// input:  [N, 32, 12, 24, 48]  float32 NCDHW
// weight: [32, 8, 3, 5, 7]     (Cin, Cout_per_group, kD, kH, kW)
// output: [N, 32, 23, 47, 95]  float32 NCDHW
// groups=4, stride=(2,2,2), padding=(1,2,3), output_padding=(1,1,1)

#define IN_C   32
#define OUT_C  32
#define IN_D   12
#define IN_H   24
#define IN_W   48
#define OUT_D  23
#define OUT_H  47
#define OUT_W  95
#define KD     3
#define KH     5
#define KW     7
#define SD     2
#define SH     2
#define SW     2
#define PD     1
#define PH     2
#define PW     3
#define GROUPS 4
#define CIN_PER_GROUP  8
#define COUT_PER_GROUP 8

__global__ void conv_transpose3d_specialized_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N)
{
    // Each thread computes one output element (n, oc, od, oh, ow)
    // Grid: (N * OUT_C, OUT_D * OUT_H, OUT_W)
    int nc_idx = blockIdx.x;
    int n   = nc_idx / OUT_C;
    int oc  = nc_idx % OUT_C;

    int dh_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int od  = dh_idx / OUT_H;
    int oh  = dh_idx % OUT_H;
    int ow  = blockIdx.z * blockDim.x + threadIdx.x;

    if (n >= N || od >= OUT_D || oh >= OUT_H || ow >= OUT_W) return;

    int g         = oc / COUT_PER_GROUP;
    int oc_local  = oc % COUT_PER_GROUP;
    int ic_base   = g * CIN_PER_GROUP;

    // For conv_transpose3d output at position (od, oh, ow):
    // input position: id = (od + PD - kd) / SD  (must be integer, in [0, IN_D))
    // => kd must satisfy: (od + PD - kd) % SD == 0 and 0 <= (od+PD-kd)/SD < IN_D
    // Starting kernel indices (phase = (od+PD) % SD)
    int phd = (od + PD) % SD;
    int phh = (oh + PH) % SH;
    int phw = (ow + PW) % SW;

    float acc = 0.0f;

    for (int ic = 0; ic < CIN_PER_GROUP; ++ic) {
        // weight layout: [Cin, Cout_per_group, kD, kH, kW]
        // global ic index: ic_base + ic
        int w_ic_off = (ic_base + ic) * (COUT_PER_GROUP * KD * KH * KW)
                     + oc_local * (KD * KH * KW);

        for (int kd = phd; kd < KD; kd += SD) {
            int id = (od + PD - kd) / SD;
            if (id < 0 || id >= IN_D) continue;

            for (int kh = phh; kh < KH; kh += SH) {
                int ih = (oh + PH - kh) / SH;
                if (ih < 0 || ih >= IN_H) continue;

                for (int kw = phw; kw < KW; kw += SW) {
                    int iw = (ow + PW - kw) / SW;
                    if (iw < 0 || iw >= IN_W) continue;

                    // input index: [n, ic_base+ic, id, ih, iw]
                    int in_idx = ((n * IN_C + ic_base + ic) * IN_D + id) * IN_H * IN_W
                               + ih * IN_W + iw;

                    // weight index
                    int wt_idx = w_ic_off + kd * KH * KW + kh * KW + kw;

                    acc += input[in_idx] * weight[wt_idx];
                }
            }
        }
    }

    // output index: [n, oc, od, oh, ow]
    int out_idx = ((n * OUT_C + oc) * OUT_D + od) * OUT_H * OUT_W
                + oh * OUT_W + ow;
    output[out_idx] = acc;
}

torch::Tensor stark_conv_transpose3d_fast(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "Tensors must be on CUDA");
    TORCH_CHECK(input.is_contiguous() && weight.is_contiguous(), "Tensors must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32 && weight.dtype() == torch::kFloat32,
                "Tensors must be float32");
    int N = input.size(0);
    TORCH_CHECK(input.size(1) == IN_C && input.size(2) == IN_D &&
                input.size(3) == IN_H && input.size(4) == IN_W,
                "Input shape mismatch for specialized kernel");
    TORCH_CHECK(weight.size(0) == IN_C && weight.size(1) == COUT_PER_GROUP &&
                weight.size(2) == KD && weight.size(3) == KH && weight.size(4) == KW,
                "Weight shape mismatch for specialized kernel");

    auto output = torch::zeros({N, OUT_C, OUT_D, OUT_H, OUT_W}, input.options());

    // Grid: (N*OUT_C, ceil(OUT_D*OUT_H / blockDim.y), ceil(OUT_W / blockDim.x))
    dim3 block(32, 8, 1);
    int dh_tiles = (OUT_D * OUT_H + block.y - 1) / block.y;
    dim3 grid(N * OUT_C, dh_tiles, (OUT_W + block.x - 1) / block.x);

    conv_transpose3d_specialized_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel error: ", cudaGetErrorString(err));

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a 3D transposed convolution operation with asymmetric input and kernel, and optional stride.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
